/**
 * Minimal emulation of the CPython exception objects that the original script
 * can surface, plus the interpreter's top-level traceback rendering.
 *
 * Only the pieces the migrated program actually needs are modelled: a
 * `ValueError` carrying a message, and a printer that reproduces the frame
 * stack the frozen executable writes to stderr before exiting with status 1.
 */

/** Equivalent of Python's `ValueError`. */
export class ValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
    /**
     * Frames pushed by the library code that raised, innermost last, mirroring
     * the `File "...", line N, in name` lines CPython prints.
     */
    this.pyFrames = [];
  }
}

/**
 * Records a Python-side call frame on an exception as it propagates outward.
 * Frames are stored innermost-first and reversed at render time so the output
 * matches CPython's outermost-to-innermost traceback order.
 */
export function addFrame(error, file, line, name) {
  if (error instanceof ValueError) {
    error.pyFrames.push({ file, line, name });
  }
  return error;
}

/**
 * Renders a traceback in CPython's format.
 *
 * The frozen build cannot read the original sources, so the source-echo lines
 * are omitted here exactly as they are when the executable runs outside the
 * directory holding `test7.py`.
 */
export function formatTraceback(error, callerFrames = []) {
  const frames = [...callerFrames, ...[...error.pyFrames].reverse()];
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
  }
  lines.push(`${error.name}: ${error.message}`);
  return lines.join('\n') + '\n';
}

