/**
 * Helpers reproducing the `bytes` semantics the original script relies on:
 * `str.encode()` (UTF-8) and `repr(bytes)` as rendered by `print`.
 */

/** Equivalent of Python's `str.encode()` with the default UTF-8 codec. */
export function encodeUtf8(text) {
  const bytes = [];
  for (let i = 0; i < text.length; i++) {
    let code = text.codePointAt(i);
    if (code > 0xffff) i++; // consume the low surrogate of an astral pair

    if (code < 0x80) {
      bytes.push(code);
    } else if (code < 0x800) {
      bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f));
    } else if (code < 0x10000) {
      bytes.push(0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
    } else {
      bytes.push(
        0xf0 | (code >> 18),
        0x80 | ((code >> 12) & 0x3f),
        0x80 | ((code >> 6) & 0x3f),
        0x80 | (code & 0x3f),
      );
    }
  }
  return bytes;
}

const SHORT_ESCAPES = { 0x09: '\\t', 0x0a: '\\n', 0x0d: '\\r', 0x5c: '\\\\' };

/**
 * Equivalent of Python's `repr()` for a `bytes` object, i.e. what `print`
 * writes for one: a `b'...'` literal where printable ASCII stays verbatim and
 * everything else becomes `\t`, `\n`, `\r` or `\xHH`.
 *
 * As in CPython the quote character switches to `"` when the payload contains
 * a single quote but no double quote.
 */
export function bytesRepr(bytes) {
  const hasSingle = bytes.includes(0x27);
  const hasDouble = bytes.includes(0x22);
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const quoteByte = quote.charCodeAt(0);

  let out = `b${quote}`;
  for (const byte of bytes) {
    if (byte === quoteByte) {
      out += '\\' + quote;
    } else if (byte in SHORT_ESCAPES) {
      out += SHORT_ESCAPES[byte];
    } else if (byte >= 0x20 && byte < 0x7f) {
      out += String.fromCharCode(byte);
    } else {
      out += '\\x' + byte.toString(16).padStart(2, '0');
    }
  }
  return out + quote;
}

