/**
 * Arithmetic in GF(2^8) with the AES reduction polynomial (0x11b) and the
 * lookup tables derived from it.
 *
 * The tables are computed at import time rather than hard-coded so the
 * constants are auditable instead of transcribed.
 */

/** Multiplies a byte by x (i.e. by 2) modulo the AES polynomial. */
export function xtime(a) {
  return ((a << 1) ^ (a & 0x80 ? 0x1b : 0)) & 0xff;
}

/** Multiplies two bytes in GF(2^8). */
export function gmul(a, b) {
  let result = 0;
  while (b) {
    if (b & 1) result ^= a;
    a = xtime(a);
    b >>= 1;
  }
  return result & 0xff;
}

// Exponential / logarithm tables for the generator 3, used to invert bytes.
const EXP = new Uint8Array(256);
const LOG = new Uint8Array(256);
{
  let value = 1;
  for (let i = 0; i < 255; i++) {
    EXP[i] = value;
    LOG[value] = i;
    value ^= xtime(value); // value *= 3
  }
  EXP[255] = EXP[0];
}

/** Multiplicative inverse in GF(2^8); 0 maps to 0 by convention. */
function inverse(a) {
  return a === 0 ? 0 : EXP[255 - LOG[a]];
}

function rotl8(a, shift) {
  return ((a << shift) | (a >> (8 - shift))) & 0xff;
}

/** The AES substitution box: inverse in GF(2^8) followed by the affine map. */
export const SBOX = new Uint8Array(256);
for (let i = 0; i < 256; i++) {
  const b = inverse(i);
  SBOX[i] = (b ^ rotl8(b, 1) ^ rotl8(b, 2) ^ rotl8(b, 3) ^ rotl8(b, 4) ^ 0x63) & 0xff;
}

/** Round constants for the key schedule: RCON[i] = x^(i-1) in GF(2^8). */
export const RCON = new Uint8Array(16);
{
  let value = 1;
  for (let i = 1; i < RCON.length; i++) {
    RCON[i] = value;
    value = xtime(value);
  }
}

