/**
 * The raw AES block cipher (FIPS-197), matching `pyaes.AES`.
 *
 * Only the encryption direction is needed by the migrated script, so the
 * inverse cipher is not implemented.
 */

import { SBOX, RCON, gmul } from './galois.mjs';
import { ValueError, addFrame } from '../pyerrors.mjs';

const BLOCK_SIZE = 16;

/** Rounds performed for each supported key length, keyed by bytes of key. */
const ROUNDS_BY_KEY_SIZE = { 16: 10, 24: 12, 32: 14 };

/**
 * Expands the cipher key into `4 * (rounds + 1)` words, returned flattened to
 * bytes in the same column-major order the state uses.
 */
function expandKey(key, rounds) {
  const nk = key.length / 4;
  const totalWords = 4 * (rounds + 1);
  const schedule = new Uint8Array(totalWords * 4);
  schedule.set(key, 0);

  for (let i = nk; i < totalWords; i++) {
    const prev = (i - 1) * 4;
    let t0 = schedule[prev];
    let t1 = schedule[prev + 1];
    let t2 = schedule[prev + 2];
    let t3 = schedule[prev + 3];

    if (i % nk === 0) {
      // RotWord, then SubWord, then XOR with the round constant.
      [t0, t1, t2, t3] = [SBOX[t1] ^ RCON[i / nk], SBOX[t2], SBOX[t3], SBOX[t0]];
    } else if (nk > 6 && i % nk === 4) {
      [t0, t1, t2, t3] = [SBOX[t0], SBOX[t1], SBOX[t2], SBOX[t3]];
    }

    const back = (i - nk) * 4;
    const out = i * 4;
    schedule[out] = schedule[back] ^ t0;
    schedule[out + 1] = schedule[back + 1] ^ t1;
    schedule[out + 2] = schedule[back + 2] ^ t2;
    schedule[out + 3] = schedule[back + 3] ^ t3;
  }
  return schedule;
}

function addRoundKey(state, schedule, round) {
  const offset = round * BLOCK_SIZE;
  for (let i = 0; i < BLOCK_SIZE; i++) state[i] ^= schedule[offset + i];
}

function subBytes(state) {
  for (let i = 0; i < BLOCK_SIZE; i++) state[i] = SBOX[state[i]];
}

/** Rotates row r of the state left by r positions (state[i] holds row i % 4). */
function shiftRows(state) {
  for (let row = 1; row < 4; row++) {
    const a = state[row];
    const b = state[row + 4];
    const c = state[row + 8];
    const d = state[row + 12];
    const rotated = [
      [a, b, c, d],
      [b, c, d, a],
      [c, d, a, b],
      [d, a, b, c],
    ][row];
    state[row] = rotated[0];
    state[row + 4] = rotated[1];
    state[row + 8] = rotated[2];
    state[row + 12] = rotated[3];
  }
}

/** Multiplies each column by the fixed polynomial 3x^3 + x^2 + x + 2. */
function mixColumns(state) {
  for (let col = 0; col < 4; col++) {
    const i = col * 4;
    const a0 = state[i];
    const a1 = state[i + 1];
    const a2 = state[i + 2];
    const a3 = state[i + 3];
    state[i] = gmul(a0, 2) ^ gmul(a1, 3) ^ a2 ^ a3;
    state[i + 1] = a0 ^ gmul(a1, 2) ^ gmul(a2, 3) ^ a3;
    state[i + 2] = a0 ^ a1 ^ gmul(a2, 2) ^ gmul(a3, 3);
    state[i + 3] = gmul(a0, 3) ^ a1 ^ a2 ^ gmul(a3, 2);
  }
}

/** A keyed AES cipher operating on single 16-byte blocks. */
export class AES {
  constructor(key) {
    const rounds = ROUNDS_BY_KEY_SIZE[key.length];
    if (rounds === undefined) {
      // pyaes/aes.py, AES.__init__
      throw addFrame(new ValueError('Invalid key size'), 'pyaes/aes.py', 134, '__init__');
    }
    this.rounds = rounds;
    this.schedule = expandKey(Uint8Array.from(key), rounds);
  }

  /** Encrypts one 16-byte block, given and returned as arrays of byte values. */
  encrypt(plaintext) {
    if (plaintext.length !== BLOCK_SIZE) {
      throw addFrame(
        new ValueError('plaintext block must be 16 bytes'),
        'pyaes/aes.py',
        180,
        'encrypt',
      );
    }

    const state = Uint8Array.from(plaintext);
    addRoundKey(state, this.schedule, 0);
    for (let round = 1; round < this.rounds; round++) {
      subBytes(state);
      shiftRows(state);
      mixColumns(state);
      addRoundKey(state, this.schedule, round);
    }
    subBytes(state);
    shiftRows(state);
    addRoundKey(state, this.schedule, this.rounds);

    return Array.from(state);
  }
}

