/**
 * Block cipher modes of operation, matching the `pyaes` classes of the same
 * name. Only CBC is required by the migrated script.
 */

import { AES } from './aes.mjs';
import { ValueError, addFrame } from '../pyerrors.mjs';

const BLOCK_SIZE = 16;

/**
 * AES in Cipher-Block Chaining mode.
 *
 * The object is stateful: each call to `encrypt` chains off the previous
 * ciphertext block, so encrypting two blocks in sequence is equivalent to
 * encrypting their concatenation.
 */
export class AESModeOfOperationCBC {
  constructor(key, iv) {
    if (iv.length !== BLOCK_SIZE) {
      // pyaes/aes.py, AESModeOfOperationCBC.__init__ — checked before the key.
      throw addFrame(
        new ValueError('initialization vector must be 16 bytes'),
        'pyaes/aes.py',
        381,
        '__init__',
      );
    }

    try {
      this._aes = new AES(key);
    } catch (error) {
      // The key size check happens inside AES, two frames deeper.
      addFrame(error, 'pyaes/aes.py', 304, '__init__');
      addFrame(error, 'pyaes/aes.py', 385, '__init__');
      throw error;
    }

    this._lastCipherblock = Array.from(iv);
  }

  /** Encrypts one 16-byte block and returns the ciphertext byte values. */
  encrypt(plaintext) {
    if (plaintext.length !== BLOCK_SIZE) {
      throw addFrame(
        new ValueError('plaintext block must be 16 bytes'),
        'pyaes/aes.py',
        389,
        'encrypt',
      );
    }

    const precipherblock = Array.from(plaintext, (byte, i) => byte ^ this._lastCipherblock[i]);
    this._lastCipherblock = this._aes.encrypt(precipherblock);
    return [...this._lastCipherblock];
  }
}

