/**
 * Node.js port of test7.py: AES-CBC encryption of two consecutive 16-byte
 * blocks with a single stateful cipher object.
 *
 * Run as:
 *   node test7.mjs --key KEY --iv IV --data1 DATA1 --data2 DATA2
 */

import { ArgumentParser, SystemExit } from './lib/argparse.mjs';
import * as pyaes from './lib/pyaes/index.mjs';
import { encodeUtf8, bytesRepr } from './lib/pybytes.mjs';
import { ValueError, addFrame, formatTraceback } from './lib/pyerrors.mjs';

// argparse derives `prog` from the script name; the reference build reports
// itself as `test7_executable`, so usage and error text stay byte-identical.
const PROG = 'test7_executable';

function main() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument('--key', { required: true }); // 16 bytes key
  parser.addArgument('--iv', { required: true }); // 16 bytes IV
  parser.addArgument('--data1', { required: true }); // 16 bytes data
  parser.addArgument('--data2', { required: true }); // 16 bytes data
  const args = parser.parseArgs(process.argv.slice(2));

  // Create AES CBC cipher
  let aes;
  try {
    aes = new pyaes.AESModeOfOperationCBC(encodeUtf8(args.key), encodeUtf8(args.iv));
  } catch (error) {
    throw addFrame(error, 'test7.py', 13, 'main');
  }

  // Encrypt two data blocks
  let ciphertext1;
  let ciphertext2;
  try {
    ciphertext1 = aes.encrypt(encodeUtf8(args.data1)); // Encrypt first plaintext
  } catch (error) {
    throw addFrame(error, 'test7.py', 15, 'main');
  }
  try {
    ciphertext2 = aes.encrypt(encodeUtf8(args.data2)); // Encrypt second plaintext
  } catch (error) {
    throw addFrame(error, 'test7.py', 16, 'main');
  }

  console.log(bytesRepr(ciphertext1));
  console.log(bytesRepr(ciphertext2));
}

try {
  main();
} catch (error) {
  if (error instanceof SystemExit) {
    process.exitCode = error.status;
  } else if (error instanceof ValueError) {
    // Mirror the frozen interpreter: traceback on stderr, then exit status 1.
    process.stderr.write(formatTraceback(error, [{ file: 'test7.py', line: 21, name: '<module>' }]));
    process.stderr.write(
      `[PYI-${process.pid}:ERROR] Failed to execute script 'test7' due to unhandled exception!\n`,
    );
    process.exitCode = 1;
  } else {
    throw error;
  }
}

