#!/usr/bin/env node
/** Differential harness: runs the reference executable and the port on the
 *  same argv and compares stdout, exit status, and (PID line aside) stderr. */
import { execFileSync } from 'node:child_process';

const REF = '/workspace/dataset/test7_executable';
const PORT = ['/output/test7.mjs'];

function run(cmd, argv) {
  const res = { stdout: '', stderr: '', code: 0 };
  try {
    res.stdout = execFileSync(cmd[0], [...cmd.slice(1), ...argv], { encoding: 'latin1', stdio: ['ignore', 'pipe', 'pipe'] });
  } catch (e) {
    res.stdout = e.stdout ?? '';
    res.stderr = e.stderr ?? '';
    res.code = e.status ?? -1;
    return res;
  }
  return res;
}
function runBoth(argv) {
  const a = run([REF], argv);
  const b = run(['node', ...PORT], argv);
  return [a, b];
}
const norm = (s) => s.replace(/\[PYI-\d+:ERROR\]/g, '[PYI:ERROR]');

const CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=[]{};:,.<>?|~`'\" \\/";
const rnd = (n) => Array.from({ length: n }, () => CHARS[Math.floor(Math.random() * CHARS.length)]).join('');

const cases = [];
// randomized 16-byte happy paths (128-bit keys)
for (let i = 0; i < 250; i++) cases.push(['--key', rnd(16), '--iv', rnd(16), '--data1', rnd(16), '--data2', rnd(16)]);
// 192/256-bit keys
for (let i = 0; i < 60; i++) cases.push(['--key', rnd(24), '--iv', rnd(16), '--data1', rnd(16), '--data2', rnd(16)]);
for (let i = 0; i < 60; i++) cases.push(['--key', rnd(32), '--iv', rnd(16), '--data1', rnd(16), '--data2', rnd(16)]);
// all-identical / structured blocks
cases.push(['--key', '\x00'.repeat(0) + 'aaaaaaaaaaaaaaaa', '--iv', 'aaaaaaaaaaaaaaaa', '--data1', 'aaaaaaaaaaaaaaaa', '--data2', 'aaaaaaaaaaaaaaaa']);
cases.push(['--key', '0123456789abcdef', '--iv', '0123456789abcdef', '--data1', '0123456789abcdef', '--data2', 'fedcba9876543210']);
// quote-containing plaintexts exercise repr quoting
for (let i = 0; i < 40; i++) cases.push(['--key', rnd(16), '--iv', rnd(16), '--data1', rnd(16), '--data2', rnd(16)]);
// error paths
cases.push([]);
cases.push(['--help']);
cases.push(['-h']);
cases.push(['--key', 'a'.repeat(16)]);
cases.push(['--key', 'short', '--iv', 'b'.repeat(16), '--data1', 'c'.repeat(16), '--data2', 'd'.repeat(16)]);
cases.push(['--key', 'a'.repeat(16), '--iv', 'short', '--data1', 'c'.repeat(16), '--data2', 'd'.repeat(16)]);
cases.push(['--key', 'a'.repeat(16), '--iv', 'b'.repeat(16), '--data1', 'short', '--data2', 'd'.repeat(16)]);
cases.push(['--key', 'a'.repeat(16), '--iv', 'b'.repeat(16), '--data1', 'c'.repeat(16), '--data2', '']);
cases.push(['--key', 'a'.repeat(17), '--iv', 'b'.repeat(16), '--data1', 'c'.repeat(16), '--data2', 'd'.repeat(16)]);
cases.push(['--key', 'a'.repeat(16), '--iv', 'b'.repeat(16), '--data1', 'c'.repeat(16), '--data2', 'd'.repeat(16), '--extra', 'x']);
cases.push(['--ke', 'a'.repeat(16), '--iv', 'b'.repeat(16), '--data1', 'c'.repeat(16), '--data2', 'd'.repeat(16)]);
cases.push(['--d', 'x', '--key', 'a'.repeat(16)]);
cases.push(['--key=' + 'a'.repeat(16), '--iv=' + 'b'.repeat(16), '--data1=' + 'c'.repeat(16), '--data2=' + 'd'.repeat(16)]);
cases.push(['--key=-' + 'a'.repeat(15), '--iv', 'b'.repeat(16), '--data1', 'c'.repeat(16), '--data2', 'd'.repeat(16)]);
cases.push(['--key', '-' + 'a'.repeat(15), '--iv', 'b'.repeat(16), '--data1', 'c'.repeat(16), '--data2', 'd'.repeat(16)]);
cases.push(['--key', '-123456789012345', '--iv', 'b'.repeat(16), '--data1', 'c'.repeat(16), '--data2', 'd'.repeat(16)]);
cases.push(['--key', 'a'.repeat(16), '--key', '1'.repeat(16), '--iv', 'b'.repeat(16), '--data1', 'c'.repeat(16), '--data2', 'd'.repeat(16)]);
cases.push(['--key', 'a'.repeat(16), '--iv', 'b'.repeat(16), '--data1', 'c'.repeat(16), '--', '--data2', 'd'.repeat(16)]);
cases.push(['-x']);
cases.push(['--key', 'a'.repeat(16), '-h']);
cases.push(['--key=', '--iv', 'b'.repeat(16), '--data1', 'c'.repeat(16), '--data2', 'd'.repeat(16)]);
cases.push(['positional', '--key', 'a'.repeat(16), '--iv', 'b'.repeat(16), '--data1', 'c'.repeat(16), '--data2', 'd'.repeat(16)]);
// multi-byte UTF-8 (14 chars + 2-byte char = 16 bytes) and length mismatches
cases.push(['--key', 'a'.repeat(14) + 'é', '--iv', 'b'.repeat(16), '--data1', 'c'.repeat(16), '--data2', 'd'.repeat(16)]);
cases.push(['--key', 'a'.repeat(16), '--iv', 'b'.repeat(16), '--data1', 'ccccccccccccc' + '€', '--data2', 'd'.repeat(16)]);
cases.push(['--key', 'a'.repeat(16), '--iv', 'b'.repeat(16), '--data1', 'cccccccccccc' + '𝄞', '--data2', 'd'.repeat(16)]);
cases.push(['--key', 'a'.repeat(15) + 'é', '--iv', 'b'.repeat(16), '--data1', 'c'.repeat(16), '--data2', 'd'.repeat(16)]);
// bytes that force repr escaping of quotes/backslashes in the plaintext space
for (let i = 0; i < 20; i++) cases.push(['--key', rnd(16), '--iv', rnd(16), '--data1', "''''''''''''''''", '--data2', '\\'.repeat(16)]);

let fails = 0;
for (const argv of cases) {
  const [a, b] = runBoth(argv);
  const same = a.stdout === b.stdout && a.code === b.code && norm(a.stderr) === norm(b.stderr);
  if (!same) {
    fails++;
    if (fails <= 8) {
      console.log('MISMATCH argv=' + JSON.stringify(argv));
      if (a.stdout !== b.stdout) console.log('  stdout ref=' + JSON.stringify(a.stdout) + '\n         got=' + JSON.stringify(b.stdout));
      if (a.code !== b.code) console.log(`  code ref=${a.code} got=${b.code}`);
      if (norm(a.stderr) !== norm(b.stderr)) console.log('  stderr ref=' + JSON.stringify(norm(a.stderr)) + '\n         got=' + JSON.stringify(norm(b.stderr)));
    }
  }
}
console.log(`\n${cases.length - fails}/${cases.length} cases match`);
process.exitCode = fails ? 1 : 0;

