/**
 * A faithful subset of Python's `argparse`, sufficient to parse the original
 * script's command line identically.
 *
 * The structure mirrors CPython's own two-phase algorithm because the phases
 * determine which error wins. Every token is first classified as an option
 * (`O`), a value (`A`), or the `--` terminator (`-`); only then are options
 * consumed. That ordering is what makes, say, an ambiguous abbreviation later
 * in the line outrank a missing value earlier in it.
 *
 * Behaviours reproduced from CPython:
 *   - `--opt value` and `--opt=value` forms
 *   - unambiguous long-option prefix abbreviation (`--ke` -> `--key`)
 *   - later occurrences of an option overwrite earlier ones
 *   - a `-`-prefixed token is still a value if it is a bare `-`, looks like a
 *     negative number, or contains a space
 *   - `--` ends option parsing, is itself reported as unrecognized, and may sit
 *     between an option and its value
 *   - the required-arguments error is reported before unrecognized arguments
 *   - errors print usage plus a `prog: error: ...` line to stderr and exit 2
 *   - `-h` prints help to stdout and exits 0
 */

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
const HELP_INDENT = 2;
const MAX_HELP_POSITION = 24;

/** Raised internally to unwind to the top-level exit handling. */
export class SystemExit extends Error {
  constructor(status) {
    super(`SystemExit: ${status}`);
    this.status = status;
  }
}

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog;
    this.actions = [
      {
        option: '-h',
        aliases: ['--help'],
        dest: 'help',
        isHelp: true,
        required: false,
        metavar: null,
        help: 'show this help message and exit',
      },
    ];
  }

  /** Equivalent of `add_argument('--name', type=str, required=...)`. */
  addArgument(option, { required = false } = {}) {
    const dest = option.replace(/^--?/, '').replace(/-/g, '_');
    this.actions.push({
      option,
      aliases: [],
      dest,
      isHelp: false,
      required,
      metavar: dest.toUpperCase(),
      help: null,
    });
    return this;
  }

  /** Every option string, in declaration order, paired with its action. */
  _optionStrings() {
    return this.actions.flatMap((action) =>
      [action.option, ...action.aliases].map((name) => [name, action]),
    );
  }

  /** How argparse names an action in error messages: all its option strings. */
  _actionName(action) {
    return [action.option, ...action.aliases].join('/');
  }

  formatUsage() {
    const parts = this.actions.map((action) =>
      action.isHelp
        ? '[-h]'
        : action.required
          ? `${action.option} ${action.metavar}`
          : `[${action.option} ${action.metavar}]`,
    );
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    // argparse aligns help text at `min(longest invocation + 2, 24)` columns,
    // where each invocation length includes the two-space indent.
    const invocations = this.actions.map((action) =>
      action.isHelp
        ? [action.option, ...action.aliases].join(', ')
        : `${action.option} ${action.metavar}`,
    );
    const longest = Math.max(...invocations.map((text) => text.length + HELP_INDENT));
    const helpPosition = Math.min(longest + 2, MAX_HELP_POSITION);

    let out = `${this.formatUsage()}\noptions:\n`;
    this.actions.forEach((action, i) => {
      const invocation = ' '.repeat(HELP_INDENT) + invocations[i];
      out += action.help ? invocation.padEnd(helpPosition) + action.help + '\n' : invocation + '\n';
    });
    return out;
  }

  /** Prints help to stdout and exits successfully, as the help action does. */
  _printHelp() {
    process.stdout.write(this.formatHelp());
    throw new SystemExit(0);
  }

  /** Writes usage plus the error message to stderr and exits with status 2. */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /**
   * Candidate interpretations of a `-`-prefixed token by prefix, mirroring
   * `_get_option_tuples`. Long options match on any prefix; a single-dash
   * token may also be a short option with its value concatenated.
   */
  _optionTuples(token) {
    const tuples = [];
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const prefix = eq === -1 ? token : token.slice(0, eq);
      const explicitValue = eq === -1 ? null : token.slice(eq + 1);
      for (const [optionString, action] of this._optionStrings()) {
        if (optionString.startsWith(prefix)) tuples.push({ action, optionString, explicitValue });
      }
    } else {
      const shortPrefix = token.slice(0, 2);
      const shortExplicitValue = token.slice(2);
      for (const [optionString, action] of this._optionStrings()) {
        if (optionString === shortPrefix) {
          tuples.push({ action, optionString, explicitValue: shortExplicitValue });
        } else if (optionString.startsWith(token)) {
          tuples.push({ action, optionString, explicitValue: null });
        }
      }
    }
    return tuples;
  }

  /**
   * Classifies one token, mirroring `_parse_optional`. Returns `null` when the
   * token is a value, or a tuple whose `action` is `null` for an option the
   * parser does not know.
   */
  _parseOptional(token) {
    if (token === '' || !token.startsWith('-')) return null;

    const options = this._optionStrings();
    const exact = options.find(([optionString]) => optionString === token);
    if (exact) return { action: exact[1], optionString: token, explicitValue: null };

    if (token.length === 1) return null; // a bare '-' is a value

    const eq = token.indexOf('=');
    if (eq !== -1) {
      const name = token.slice(0, eq);
      const hit = options.find(([optionString]) => optionString === name);
      if (hit) return { action: hit[1], optionString: name, explicitValue: token.slice(eq + 1) };
    }

    const tuples = this._optionTuples(token);
    if (tuples.length > 1) {
      const candidates = tuples.map((tuple) => tuple.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${candidates}`);
    }
    if (tuples.length === 1) return tuples[0];

    if (NEGATIVE_NUMBER.test(token)) return null; // no option looks numeric
    if (token.includes(' ')) return null;

    return { action: null, optionString: token, explicitValue: null };
  }

  /**
   * Parses `argv` (option and value tokens only, no program name) and returns
   * an object keyed by destination name.
   */
  parseArgs(argv) {
    // Phase 1: classify every token.
    const pattern = [];
    const optionTuples = new Map();
    for (let i = 0; i < argv.length; i++) {
      if (argv[i] === '--') {
        pattern.push('-');
        while (pattern.length < argv.length) pattern.push('A');
        break;
      }
      const tuple = this._parseOptional(argv[i]);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(i, tuple);
        pattern.push('O');
      }
    }

    // Phase 2: consume options left to right; unclaimed tokens become extras.
    const values = {};
    const extras = [];
    const optionIndices = [...optionTuples.keys()];
    const lastOptionIndex = optionIndices.length ? Math.max(...optionIndices) : -1;

    let i = 0;
    while (i <= lastOptionIndex) {
      if (!optionTuples.has(i)) {
        // No positional actions exist, so tokens before the next option are
        // reported rather than consumed.
        const next = optionIndices.find((index) => index > i);
        extras.push(...argv.slice(i, next));
        i = next;
        continue;
      }
      i = this._consumeOptional(argv, pattern, optionTuples.get(i), i, values, extras);
    }
    extras.push(...argv.slice(i));

    const missing = this.actions
      .filter((action) => action.required && values[action.dest] === undefined)
      .map((action) => action.option);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }

  /** Applies one option at `index` and returns the index to continue from. */
  _consumeOptional(argv, pattern, tuple, index, values, extras) {
    const { action, optionString, explicitValue } = tuple;

    if (action === null) {
      // An unknown option is reported but never swallows a following value.
      extras.push(argv[index]);
      return index + 1;
    }

    if (action.isHelp) {
      // The help action runs before any complaint about a leftover tail, so
      // `-hx` still prints help; a long option with a value is an error.
      const concatenated = !optionString.startsWith('--') && explicitValue;
      if (explicitValue !== null && !concatenated) {
        this.error(
          `argument ${this._actionName(action)}: ignored explicit argument '${explicitValue}'`,
        );
      }
      this._printHelp();
    }

    if (explicitValue !== null) {
      values[action.dest] = explicitValue;
      return index + 1;
    }

    // A single value, which a `--` terminator may be interleaved with: the
    // nargs pattern argparse matches here is `-*A-*`.
    let next = index + 1;
    while (pattern[next] === '-') next++;
    if (pattern[next] !== 'A') {
      this.error(`argument ${this._actionName(action)}: expected one argument`);
    }
    values[action.dest] = argv[next];
    next++;
    while (pattern[next] === '-') next++;
    return next;
  }
}

