      return index + 1;
    }

    // A single value, which a `--` terminator may be interleaved with: the
    // nargs pattern argparse matches here is `-*A-*`.
    let next = index + 1;
    while (pattern[next] === '-') next++;
    if (pattern[next] !== 'A') {
      this.error(`argument ${this._actionName(action)}: expected one argument`);
    }
    values[action.dest] = argv[next];
    next++;
    while (pattern[next] === '-') next++;
    return next;
  }
}

toolUseResult.originalFile:
/**
 * A small subset of Python's `argparse`, sufficient to parse the original
 * script's command line identically.
 *
 * Behaviours reproduced from CPython's implementation:
 *   - `--opt value` and `--opt=value` forms
 *   - unambiguous long-option prefix abbreviation (`--ke` -> `--key`)
 *   - later occurrences of an option overwrite earlier ones
 *   - values that look like negative numbers are accepted as values, while
 *     other `-`-prefixed tokens are treated as options
 *   - `--` ends option parsing
 *   - the required-arguments error is reported before unrecognized arguments
 *   - errors print usage plus a `prog: error: ...` line to stderr and exit 2
 *   - `-h` prints help to stdout and exits 0
 */

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
const HELP_INDENT = 2;
const MAX_HELP_POSITION = 24;

/** Raised internally to unwind to the top-level exit handling. */
class SystemExit extends Error {
  constructor(status) {
    super(`SystemExit: ${status}`);
    this.status = status;
  }
}

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog;
    this.actions = [
      { option: '-h', aliases: ['--help'], dest: 'help', isHelp: true, metavar: null,
        help: 'show this help message and exit' },
    ];
  }

  /** Equivalent of `add_argument('--name', type=str, required=...)`. */
  addArgument(option, { required = false } = {}) {
    const dest = option.replace(/^--?/, '').replace(/-/g, '_');
    this.actions.push({
      option,
      aliases: [],
      dest,
      required,
      metavar: dest.toUpperCase(),
      help: null,
    });
    return this;
  }

  /** All option strings, in declaration order, mapped to their action. */
  _optionStrings() {
    const entries = [];
    for (const action of this.actions) {
      for (const name of [action.option, ...action.aliases]) entries.push([name, action]);
    }
    return entries;
  }

  formatUsage() {
    const parts = this.actions.map((action) =>
      action.isHelp
        ? '[-h]'
        : action.required
          ? `${action.option} ${action.metavar}`
          : `[${action.option} ${action.metavar}]`,
    );
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    // argparse aligns help text at `min(longest invocation + 2, 24)` columns,
    // where the invocation length includes the two-space indent.
    const invocations = this.actions.map((action) =>
      action.isHelp
        ? [action.option, ...action.aliases].join(', ')
        : `${action.option} ${action.metavar}`,
    );
    const longest = Math.max(...invocations.map((text) => text.length + HELP_INDENT));
    const helpPosition = Math.min(longest + 2, MAX_HELP_POSITION);

    let out = this.formatUsage() + '\noptions:\n';
    this.actions.forEach((action, i) => {
      const invocation = ' '.repeat(HELP_INDENT) + invocations[i];
      out += action.help
        ? invocation.padEnd(helpPosition) + action.help + '\n'
        : invocation + '\n';
    });
    return out;
  }

  /** Writes usage plus the error message to stderr and exits with status 2. */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /**
   * Resolves one `--opt`/`--opt=value` token to its action, honouring prefix
   * abbreviation and reporting ambiguity the way argparse does.
   */
  _matchOption(token) {
    const eq = token.indexOf('=');
    const name = eq === -1 ? token : token.slice(0, eq);
    const explicitValue = eq === -1 ? null : token.slice(eq + 1);

    const options = this._optionStrings();
    const exact = options.find(([optionString]) => optionString === name);
    if (exact) return { action: exact[1], explicitValue, name };

    if (!name.startsWith('--')) return null;
    const prefixed = options.filter(([optionString]) => optionString.startsWith(name));
    if (prefixed.length === 1) return { action: prefixed[0][1], explicitValue, name };
    if (prefixed.length > 1) {
      const candidates = prefixed.map(([optionString]) => optionString).join(', ');
      this.error(`ambiguous option: ${name} could match ${candidates}`);
    }
    return null;
  }

  /**
   * Parses `argv` (option/value tokens only, no program name) and returns an
   * object keyed by destination name.
   */
  parseArgs(argv) {
    const values = {};
    const extras = [];
    let optionsEnabled = true;

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];

      if (optionsEnabled && token === '--') {
        optionsEnabled = false;
        continue;
      }

      const looksLikeOption =
        optionsEnabled &&
        token.length > 1 &&
        token.startsWith('-') &&
        !NEGATIVE_NUMBER.test(token);

      if (!looksLikeOption) {
        extras.push(token);
        continue;
      }

      const match = this._matchOption(token);
      if (!match) {
        extras.push(token);
        continue;
      }
      const { action, explicitValue, name } = match;

      if (action.isHelp) {
        process.stdout.write(this.formatHelp());
        throw new SystemExit(0);
      }

      if (explicitValue !== null) {
        values[action.dest] = explicitValue;
        continue;
      }

      const next = argv[i + 1];
      const nextIsOption =
        next !== undefined &&
        optionsEnabled &&
        next.length > 1 &&
        next.startsWith('-') &&
        !NEGATIVE_NUMBER.test(next);
      if (next === undefined || nextIsOption) {
        this.error(`argument ${name}: expected one argument`);
      }
      values[action.dest] = next;
      i++;
    }

    const missing = this.actions
      .filter((action) => action.required && values[action.dest] === undefined)
      .map((action) => action.option);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}

export { SystemExit };

