    if (tuples.length > 1) {
      const candidates = tuples.map((tuple) => tuple.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${candidates}`);
    }
    if (tuples.length === 1) return tuples[0];

    if (NEGATIVE_NUMBER.test(token)) return null; // no option looks numeric
    if (token.includes(' ')) return null;

    return { action: null, optionString: token, explicitValue: null, sep: '' };
  }

  /**
   * Parses `argv` (option and value tokens only, no program name) and returns
   * an object keyed by destination name.
   */
  parseArgs(argv) {
    // Phase 1: classify every token.
    const pattern = [];
    const optionTuples = new Map();
    for (let i = 0; i < argv.length; i++) {
      if (argv[i] === '--') {
        pattern.push('-');
        while (pattern.length < argv.length) pattern.push('A');
        break;
      }
      const tuple = this._parseOptional(argv[i]);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(i, tuple);
        pattern.push('O');
      }
    }

    // Phase 2: consume options left to right; unclaimed tokens become extras.
    const values = {};
    const extras = [];
    const optionIndices = [...optionTuples.keys()];
    const lastOptionIndex = optionIndices.length ? Math.max(...optionIndices) : -1;

