#!/usr/bin/env node
/** Fuzzes random argv token sequences (and long random happy-path runs)
 *  against both implementations. */
import { execFileSync } from 'node:child_process';

const run = (cmd, argv) => {
  try {
    return { stdout: execFileSync(cmd[0], [...cmd.slice(1), ...argv], { encoding: 'latin1', stdio: ['ignore', 'pipe', 'pipe'] }), stderr: '', code: 0 };
  } catch (e) {
    return { stdout: e.stdout ?? '', stderr: e.stderr ?? '', code: e.status ?? -1 };
  }
};
const norm = (s) => s.replace(/\[PYI-\d+:ERROR\]/g, '[PYI:ERROR]');

const CHARS = "abcXYZ019!@#$%^&*()_+-=[]{};:,.<>?|~`'\" \\/\t\n";
const rnd = (n) => Array.from({ length: n }, () => CHARS[Math.floor(Math.random() * CHARS.length)]).join('');
const pick = (a) => a[Math.floor(Math.random() * a.length)];

const TOKENS = ['--key', '--iv', '--data1', '--data2', '--ke', '--k', '--d', '--da', '--i', '-h', '--help',
  '--', '-', '', '-x', '--unknown', '--key=', '--iv=zz', '-5', '-1.25', '-a b', 'plain', '--data1=x'];

const cases = [];
for (let i = 0; i < 400; i++) {
  const n = 1 + Math.floor(Math.random() * 7);
  cases.push(Array.from({ length: n }, () => (Math.random() < 0.55 ? pick(TOKENS) : rnd(1 + Math.floor(Math.random() * 17)))));
}
for (let i = 0; i < 400; i++) {
  const klen = pick([16, 16, 16, 24, 32]);
  cases.push(['--key', rnd(klen), '--iv', rnd(16), '--data1', rnd(16), '--data2', rnd(16)]);
}

let fails = 0;
for (const argv of cases) {
  const a = run(['/workspace/dataset/test7_executable'], argv);
  const b = run(['node', '/output/test7.mjs'], argv);
  if (a.stdout !== b.stdout || a.code !== b.code || norm(a.stderr) !== norm(b.stderr)) {
    fails++;
    if (fails <= 6) {
      console.log('MISMATCH ' + JSON.stringify(argv));
      console.log('  ref  code=' + a.code + ' out=' + JSON.stringify(a.stdout) + ' err=' + JSON.stringify(norm(a.stderr)));
      console.log('  got  code=' + b.code + ' out=' + JSON.stringify(b.stdout) + ' err=' + JSON.stringify(norm(b.stderr)));
    }
  }
}
console.log(`\n${cases.length - fails}/${cases.length} fuzz cases match`);
process.exitCode = fails ? 1 : 0;

