1	/**
2	 * A faithful subset of Python's `argparse`, sufficient to parse the original
3	 * script's command line identically.
4	 *
5	 * The structure mirrors CPython's own two-phase algorithm because the phases
6	 * determine which error wins. Every token is first classified as an option
7	 * (`O`), a value (`A`), or the `--` terminator (`-`); only then are options
8	 * consumed. That ordering is what makes, say, an ambiguous abbreviation later
9	 * in the line outrank a missing value earlier in it.
10	 *
11	 * Behaviours reproduced from CPython:
12	 *   - `--opt value` and `--opt=value` forms
13	 *   - unambiguous long-option prefix abbreviation (`--ke` -> `--key`)
14	 *   - later occurrences of an option overwrite earlier ones
15	 *   - a `-`-prefixed token is still a value if it is a bare `-`, looks like a
16	 *     negative number, or contains a space
17	 *   - `--` ends option parsing and is itself reported as unrecognized; it can
18	 *     never stand in for an option's value
19	 *   - the required-arguments error is reported before unrecognized arguments
20	 *   - errors print usage plus a `prog: error: ...` line to stderr and exit 2
21	 *   - `-h` prints help to stdout and exits 0
22	 */
23	
24	const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
25	const HELP_INDENT = 2;
26	const MAX_HELP_POSITION = 24;
27	
28	/** Raised internally to unwind to the top-level exit handling. */
29	export class SystemExit extends Error {
30	  constructor(status) {
31	    super(`SystemExit: ${status}`);
32	    this.status = status;
33	  }
34	}
35	
36	export class ArgumentParser {
37	  constructor({ prog } = {}) {
38	    this.prog = prog;
39	    this.actions = [
40	      {
41	        option: '-h',
42	        aliases: ['--help'],
43	        dest: 'help',
44	        isHelp: true,
45	        required: false,
46	        metavar: null,
47	        help: 'show this help message and exit',
48	      },
49	    ];
50	  }
51	
52	  /** Equivalent of `add_argument('--name', type=str, required=...)`. */
53	  addArgument(option, { required = false } = {}) {
54	    const dest = option.replace(/^--?/, '').replace(/-/g, '_');
55	    this.actions.push({
56	      option,
57	      aliases: [],
58	      dest,
59	      isHelp: false,
60	      required,
61	      metavar: dest.toUpperCase(),
62	      help: null,
63	    });
64	    return this;
65	  }
66	
67	  /** Every option string, in declaration order, paired with its action. */
68	  _optionStrings() {
69	    return this.actions.flatMap((action) =>
70	      [action.option, ...action.aliases].map((name) => [name, action]),
71	    );
72	  }
73	
74	  /** How argparse names an action in error messages: all its option strings. */
75	  _actionName(action) {
76	    return [action.option, ...action.aliases].join('/');
77	  }
78	
79	  formatUsage() {
80	    const parts = this.actions.map((action) =>
81	      action.isHelp
82	        ? '[-h]'
83	        : action.required
84	          ? `${action.option} ${action.metavar}`
85	          : `[${action.option} ${action.metavar}]`,
86	    );
87	    return `usage: ${this.prog} ${parts.join(' ')}\n`;
88	  }
89	
90	  formatHelp() {
91	    // argparse aligns help text at `min(longest invocation + 2, 24)` columns,
92	    // where each invocation length includes the two-space indent.
93	    const invocations = this.actions.map((action) =>
94	      action.isHelp
95	        ? [action.option, ...action.aliases].join(', ')
96	        : `${action.option} ${action.metavar}`,
97	    );
98	    const longest = Math.max(...invocations.map((text) => text.length + HELP_INDENT));
99	    const helpPosition = Math.min(longest + 2, MAX_HELP_POSITION);
100	
101	    let out = `${this.formatUsage()}\noptions:\n`;
102	    this.actions.forEach((action, i) => {
103	      const invocation = ' '.repeat(HELP_INDENT) + invocations[i];
104	      out += action.help ? invocation.padEnd(helpPosition) + action.help + '\n' : invocation + '\n';
105	    });
106	    return out;
107	  }
108	
109	  /** Prints help to stdout and exits successfully, as the help action does. */
110	  _printHelp() {
111	    process.stdout.write(this.formatHelp());
112	    throw new SystemExit(0);
113	  }
114	
115	  /** Writes usage plus the error message to stderr and exits with status 2. */
116	  error(message) {
117	    process.stderr.write(this.formatUsage());
118	    process.stderr.write(`${this.prog}: error: ${message}\n`);
119	    throw new SystemExit(2);
120	  }
121	
122	  /**
123	   * Candidate interpretations of a `-`-prefixed token by prefix, mirroring
124	   * `_get_option_tuples`. Long options match on any prefix; a single-dash
125	   * token may also be a short option with its value concatenated.
126	   */
127	  _optionTuples(token) {
128	    const tuples = [];
129	    if (token.startsWith('--')) {
130	      const eq = token.indexOf('=');
131	      const prefix = eq === -1 ? token : token.slice(0, eq);
132	      const explicitValue = eq === -1 ? null : token.slice(eq + 1);
133	      const sep = eq === -1 ? '' : '=';
134	      for (const [optionString, action] of this._optionStrings()) {
135	        if (optionString.startsWith(prefix)) {
136	          tuples.push({ action, optionString, explicitValue, sep });
137	        }
138	      }
139	    } else {
140	      const shortPrefix = token.slice(0, 2);
141	      const shortExplicitValue = token.slice(2);
142	      for (const [optionString, action] of this._optionStrings()) {
143	        if (optionString === shortPrefix) {
144	          tuples.push({ action, optionString, explicitValue: shortExplicitValue, sep: '' });
145	        } else if (optionString.startsWith(token)) {
146	          tuples.push({ action, optionString, explicitValue: null, sep: '' });
147	        }
148	      }
149	    }
150	    return tuples;
151	  }
152	
153	  /**
154	   * Classifies one token, mirroring `_parse_optional`. Returns `null` when the
155	   * token is a value, or a tuple whose `action` is `null` for an option the
156	   * parser does not know.
157	   */
158	  _parseOptional(token) {
159	    if (token === '' || !token.startsWith('-')) return null;
160	
161	    const options = this._optionStrings();
162	    const exact = options.find(([optionString]) => optionString === token);
163	    if (exact) return { action: exact[1], optionString: token, explicitValue: null, sep: '' };
164	
165	    if (token.length === 1) return null; // a bare '-' is a value
166	
167	    const eq = token.indexOf('=');
168	    if (eq !== -1) {
169	      const name = token.slice(0, eq);
170	      const hit = options.find(([optionString]) => optionString === name);
171	      if (hit) {
172	        return { action: hit[1], optionString: name, explicitValue: token.slice(eq + 1), sep: '=' };
173	      }
174	    }
175	
176	    const tuples = this._optionTuples(token);
177	    if (tuples.length > 1) {
178	      const candidates = tuples.map((tuple) => tuple.optionString).join(', ');
179	      this.error(`ambiguous option: ${token} could match ${candidates}`);
180	    }
181	    if (tuples.length === 1) return tuples[0];
182	
183	    if (NEGATIVE_NUMBER.test(token)) return null; // no option looks numeric
184	    if (token.includes(' ')) return null;
185	
186	    return { action: null, optionString: token, explicitValue: null, sep: '' };
187	  }
188	
189	  /**
190	   * Parses `argv` (option and value tokens only, no program name) and returns
191	   * an object keyed by destination name.
192	   */
193	  parseArgs(argv) {
194	    // Phase 1: classify every token.
195	    const pattern = [];
196	    const optionTuples = new Map();
197	    for (let i = 0; i < argv.length; i++) {
198	      if (argv[i] === '--') {
199	        pattern.push('-');
200	        while (pattern.length < argv.length) pattern.push('A');
201	        break;
202	      }
203	      const tuple = this._parseOptional(argv[i]);
204	      if (tuple === null) {
205	        pattern.push('A');
206	      } else {
207	        optionTuples.set(i, tuple);
208	        pattern.push('O');
209	      }
210	    }
211	
212	    // Phase 2: consume options left to right; unclaimed tokens become extras.
213	    const values = {};
214	    const extras = [];
215	    const optionIndices = [...optionTuples.keys()];
216	    const lastOptionIndex = optionIndices.length ? Math.max(...optionIndices) : -1;
217	
218	    let i = 0;
219	    while (i <= lastOptionIndex) {
220	      if (!optionTuples.has(i)) {
221	        // No positional actions exist, so tokens before the next option are
222	        // reported rather than consumed.
223	        const next = optionIndices.find((index) => index > i);
224	        extras.push(...argv.slice(i, next));
225	        i = next;
226	        continue;
227	      }
228	      i = this._consumeOptional(argv, pattern, optionTuples.get(i), i, values, extras);
229	    }
230	    extras.push(...argv.slice(i));
231	
232	    const missing = this.actions
233	      .filter((action) => action.required && values[action.dest] === undefined)
234	      .map((action) => action.option);
235	    if (missing.length > 0) {
236	      this.error(`the following arguments are required: ${missing.join(', ')}`);
237	    }
238	
239	    if (extras.length > 0) {
240	      this.error(`unrecognized arguments: ${extras.join(' ')}`);
241	    }
242	
243	    return values;
244	  }
245	
246	  /** Applies one option at `index` and returns the index to continue from. */
247	  _consumeOptional(argv, pattern, tuple, index, values, extras) {
248	    const { action, optionString, explicitValue, sep } = tuple;
249	
250	    if (action === null) {
251	      // An unknown option is reported but never swallows a following value.
